export const getImageUrl = (url, defaultImg = '') => {
  if (!url) return defaultImg;
  if (typeof url === 'object') {
    url = url.formats?.large?.url ||
          url.formats?.medium?.url ||
          url.formats?.small?.url ||
          url.formats?.thumbnail?.url ||
          url.url ||
          url.attributes?.formats?.large?.url ||
          url.attributes?.formats?.medium?.url ||
          url.attributes?.formats?.small?.url ||
          url.attributes?.formats?.thumbnail?.url ||
          url.attributes?.url ||
          url.data?.attributes?.formats?.large?.url ||
          url.data?.attributes?.url ||
          url.data?.url ||
          '';
  }
  if (!url || typeof url !== 'string') return defaultImg;
  url = url.trim();

  // Preserve live WordPress Media Library URLs directly before legacy local-asset rewrites
  if (url.startsWith('/wp-content/uploads/')) {
    return WP_BASE ? `${WP_BASE}${url}` : url;
  }
  if (url.includes('/wp-content/uploads/')) {
    return url;
  }

  // If already a local asset path, return directly
  if (url.startsWith('/images/') || url.startsWith('/reports/') || url.startsWith('/documents/') || url.startsWith('/')) {
    if (url.startsWith('/uploads')) {
      const cleanUrl = url.split('?')[0];
      const filename = cleanUrl.split('/').pop().replace(/[^a-zA-Z0-9._-]/g, '_');
      if (BLOG_FILES.has(filename)) return '/images/blogs/' + filename;
      if (AWARD_FILES.has(filename)) return '/images/awards/' + filename;
      if (PROJECT_FILES.has(filename)) return '/images/projects/' + filename;
      if (LEADERSHIP_FILES.has(filename)) return '/images/leadership/' + filename;
      return '/images/uploads/' + filename;
    }
    return url;
  }

  // Handle external CMS / R2 / Strapi URLs by mapping to local origin
  if (url.includes('r2.dev/') || url.includes('onrender.com') || url.includes(':1337') || url.includes('/uploads/')) {
    const cleanUrl = url.split('?')[0];
    const filename = cleanUrl.split('/').pop().replace(/[^a-zA-Z0-9._-]/g, '_');
    if (BLOG_FILES.has(filename)) return '/images/blogs/' + filename;
    if (AWARD_FILES.has(filename)) return '/images/awards/' + filename;
    if (PROJECT_FILES.has(filename)) return '/images/projects/' + filename;
    if (LEADERSHIP_FILES.has(filename)) return '/images/leadership/' + filename;
    return '/images/uploads/' + filename;
  }

  if (url.startsWith('http://') || url.startsWith('https://') || url.startsWith('data:') || url.startsWith('blob:')) return url;
  return url;
};

// Generates guaranteed unique slug for projects, avoiding collisions for projects sharing names (like PMG Logistics Park)
export const getProjectSlug = (project) => {
  if (!project) return '';
  if (project.slug) return project.slug;
  const pName = project.name || project.projectName || project.project_name || project.title || '';
  const base = pName.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const pLoc = project.location || project.city || project.state || '';
  if (base === 'pmg-logistics-park' && pLoc) {
    const locLower = pLoc.toLowerCase();
    if (locLower.includes('neemrana')) return `${base}-neemrana`;
    if (locLower.includes('hyderabad')) return `${base}-hyderabad`;
    if (locLower.includes('kolathur') || locLower.includes('bangalore') || locLower.includes('bengaluru')) return `${base}-kolathur-bangalore`;
    const loc = locLower.replace(/[,/]/g, ' ').trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    return `${base}-${loc}`;
  }
  return base || String(project.id || '');
};
